  {"change": "removed", "requirement_id": "R-052"},
  {"change": "added", "new_text": "The AEBS shall be deactivated upon activation of an ADS feature, and shall not be able to be activated whilst an ADS feature is active.", "new_paragraph": "5.4.5.1"},
